#![forbid(unsafe_code)]
//! Source-preserving SVG reference lookup over an accepted XML token stream.

use vexel_xml::{TokenKind, XmlSpan, XmlToken};

pub const MAX_REFERENCE_IDS: usize = 65_536;
pub const REFERENCE_SLOT_CAPACITY: usize = 131_072;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ReferenceError {
    None,
    InvalidArgument,
    Unsupported,
    Limit,
    OutOfMemory,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ReferenceDiagnostic {
    pub category: ReferenceError,
    pub offset: usize,
}

impl ReferenceDiagnostic {
    const fn new(category: ReferenceError, offset: usize) -> Self {
        Self { category, offset }
    }
}

pub type ReferenceResult<T> = Result<T, ReferenceDiagnostic>;

/// An ID table that borrows its immutable source and tokens. IDs are compared
/// as their exact source bytes; entities are neither decoded nor rewritten.
#[derive(Debug)]
pub struct ReferenceIndex<'a> {
    source: &'a [u8],
    tokens: &'a [XmlToken],
    slots: Vec<u32>,
    id_count: usize,
    lookup_probes: usize,
}

impl<'a> ReferenceIndex<'a> {
    /// Creates the fixed-capacity index. Empty documents allocate no table.
    pub fn create(source: &'a [u8], tokens: &'a [XmlToken]) -> ReferenceResult<Self> {
        validate_tokens(source, tokens)?;
        let mut id_count = 0usize;
        for (i, token) in tokens.iter().enumerate() {
            if is_element(token.kind) && attr_value(source, tokens, i, b"id").is_some() {
                id_count = id_count.checked_add(1).ok_or_else(|| {
                    ReferenceDiagnostic::new(ReferenceError::Limit, token.name.offset)
                })?;
                if id_count > MAX_REFERENCE_IDS {
                    return Err(ReferenceDiagnostic::new(ReferenceError::Limit, token.name.offset));
                }
            }
        }
        let mut index = Self { source, tokens, slots: Vec::new(), id_count, lookup_probes: 0 };
        if id_count == 0 { return Ok(index); }

        index.slots.try_reserve_exact(REFERENCE_SLOT_CAPACITY).map_err(|_| {
            ReferenceDiagnostic::new(ReferenceError::OutOfMemory, 0)
        })?;
        index.slots.resize(REFERENCE_SLOT_CAPACITY, 0);
        for (i, token) in tokens.iter().enumerate() {
            if !is_element(token.kind) { continue; }
            let Some(id) = attr_value(source, tokens, i, b"id") else { continue };
            if id.length == 0 {
                return Err(ReferenceDiagnostic::new(ReferenceError::Unsupported, id.offset));
            }
            if i >= u32::MAX as usize {
                return Err(ReferenceDiagnostic::new(ReferenceError::Limit, token.name.offset));
            }
            let mut slot = (span_hash(source, id)? as usize) & (REFERENCE_SLOT_CAPACITY - 1);
            loop {
                let occupied = index.slots[slot];
                if occupied == 0 { index.slots[slot] = (i + 1) as u32; break; }
                let previous = occupied as usize - 1;
                let old_id = attr_value(source, tokens, previous, b"id").ok_or_else(|| {
                    ReferenceDiagnostic::new(ReferenceError::InvalidArgument, token.name.offset)
                })?;
                if spans_equal(source, old_id, id)? {
                    return Err(ReferenceDiagnostic::new(ReferenceError::Unsupported, id.offset));
                }
                slot = (slot + 1) & (REFERENCE_SLOT_CAPACITY - 1);
            }
        }
        Ok(index)
    }

    /// Finds an exact raw ID and counts each occupied or terminating slot probe.
    pub fn find(&mut self, id: XmlSpan) -> Option<usize> {
        let key = span_bytes(self.source, id)?;
        if key.is_empty() || self.slots.is_empty() { return None; }
        let mut slot = hash_bytes(key) as usize & (REFERENCE_SLOT_CAPACITY - 1);
        loop {
            let occupied = self.slots[slot];
            if occupied == 0 {
                self.lookup_probes = self.lookup_probes.saturating_add(1);
                return None;
            }
            self.lookup_probes = self.lookup_probes.saturating_add(1);
            let candidate = occupied as usize - 1;
            let Some(candidate_token) = self.tokens.get(candidate) else { return None };
            let Some(candidate_id) = attr_value(self.source, self.tokens, candidate, b"id") else {
                return None;
            };
            if candidate_token.kind != TokenKind::StartElement && candidate_token.kind != TokenKind::EmptyElement {
                return None;
            }
            if spans_equal(self.source, candidate_id, id).unwrap_or(false) { return Some(candidate); }
            slot = (slot + 1) & (REFERENCE_SLOT_CAPACITY - 1);
        }
    }

    pub fn id_count(&self) -> usize { self.id_count }

    /// Bytes in the actual allocated table, zero for an empty index.
    pub fn storage_bytes(&self) -> usize {
        self.slots.capacity().checked_mul(core::mem::size_of::<u32>()).unwrap_or(0)
    }

    pub fn lookup_probes(&self) -> usize { self.lookup_probes }
}

/// Finds the matching close token for a supported, nonempty definition node.
pub fn definition_end(source: &[u8], tokens: &[XmlToken], start: usize) -> Option<usize> {
    validate_tokens(source, tokens).ok()?;
    let token = tokens.get(start)?;
    if !is_element(token.kind) || token.prefix.length != 0 ||
        !one_of(span_bytes(source, token.local_name)?, &[b"defs", b"symbol", b"marker", b"clipPath"])
    { return None; }
    if token.kind == TokenKind::EmptyElement { return Some(start); }
    tokens.iter().enumerate().skip(start + 1).find_map(|(i, close)| {
        (close.kind == TokenKind::EndElement && close.depth == token.depth).then_some(i)
    })
}

pub fn attributes_supported(source: &[u8], tokens: &[XmlToken], element: usize,
                            root: bool, kind: XmlSpan) -> bool {
    if validate_tokens(source, tokens).is_err() { return false; }
    attributes_supported_inner(source, tokens, element, root, kind)
}

pub fn xlink_is_bound(source: &[u8], tokens: &[XmlToken]) -> bool {
    if validate_tokens(source, tokens).is_err() { return false; }
    for (i, token) in tokens.iter().enumerate() {
        if token.kind != TokenKind::StartElement || token.depth != 0 { continue; }
        for attr in attributes(tokens, i) {
            if span_eq(source, attr.name, b"xmlns:xlink") &&
                span_eq(source, attr.value, b"http://www.w3.org/1999/xlink") { return true; }
        }
        return false;
    }
    false
}

pub fn use_attributes_supported(source: &[u8], tokens: &[XmlToken], element: usize) -> bool {
    if validate_tokens(source, tokens).is_err() { return false; }
    for attr in attributes(tokens, element) {
        let name = attr.local_name;
        if attr.prefix.length != 0 {
            if !span_eq(source, attr.prefix, b"xlink") || !span_eq(source, name, b"href") ||
                !xlink_is_bound(source, tokens) { return false; }
            continue;
        }
        if !one_of(span_bytes(source, name).unwrap_or_default(), USE_ALLOWED) { return false; }
    }
    tokens.get(element).is_some_and(|t| is_element(t.kind))
}

const COMMON: &[&[u8]] = &[
    b"fill", b"fill-rule", b"transform", b"clip-path", b"filter", b"mask",
    b"mix-blend-mode", b"isolation", b"vector-effect", b"shape-rendering",
    b"paint-order", b"marker", b"marker-start", b"marker-mid", b"marker-end",
    b"mask-type", b"color-interpolation-filters", b"systemLanguage",
    b"requiredFeatures", b"requiredExtensions", b"fill-opacity", b"stroke-opacity",
    b"opacity", b"visibility", b"display", b"color", b"stroke", b"stroke-width",
    b"stroke-linecap", b"stroke-linejoin", b"stroke-miterlimit", b"stroke-dasharray",
    b"stroke-dashoffset", b"font-family", b"font-size", b"font-weight", b"font-style",
    b"text-anchor", b"letter-spacing", b"word-spacing",
];
const META: &[&[u8]] = &[b"id", b"class", b"style"];
const USE_ALLOWED: &[&[u8]] = &[
    b"href", b"id", b"class", b"style", b"x", b"y", b"width", b"height",
    b"preserveAspectRatio", b"fill", b"fill-rule", b"fill-opacity", b"stroke-opacity",
    b"opacity", b"visibility", b"display", b"color", b"transform", b"clip-path",
    b"filter", b"mask", b"mix-blend-mode", b"isolation", b"vector-effect",
    b"shape-rendering", b"paint-order", b"marker", b"marker-start", b"marker-mid",
    b"marker-end", b"mask-type", b"color-interpolation-filters", b"stroke",
    b"stroke-width", b"stroke-linecap", b"stroke-linejoin", b"stroke-miterlimit",
    b"stroke-dasharray", b"stroke-dashoffset", b"font-family", b"font-size",
    b"font-weight", b"font-style", b"text-anchor", b"letter-spacing", b"word-spacing",
];

fn attributes_supported_inner(source: &[u8], tokens: &[XmlToken], element: usize,
                              root: bool, kind: XmlSpan) -> bool {
    let Some(element_token) = tokens.get(element) else { return false };
    if !is_element(element_token.kind) || span_bytes(source, kind).is_none() { return false; }
    for attr in attributes(tokens, element) {
        let n = attr.local_name;
        let namespace_declaration = root && span_eq(source, attr.prefix, b"xmlns");
        let xlink_href = span_eq(source, attr.prefix, b"xlink") && span_eq(source, n, b"href");
        let common = matches_any(source, n, COMMON);
        let shape = shape_attribute(source, n, kind);
        let xml_space = span_eq(source, attr.prefix, b"xml") && span_eq(source, n, b"space") &&
            one_of(span_bytes(source, kind).unwrap_or_default(), &[b"text", b"tspan"]);
        if attr.prefix.length != 0 && !namespace_declaration && !xml_space &&
            !(xlink_href && one_of(span_bytes(source, kind).unwrap_or_default(), &[b"image", b"a"])) {
            if common || shape || xlink_href { return false; }
            continue;
        }
        let k = span_bytes(source, kind).unwrap_or_default();
        let metadata = matches_any(source, n, META);
        let ok = if root {
            metadata || common || span_eq(source, n, b"xmlns") || namespace_declaration ||
                one_of(span_bytes(source, n).unwrap_or_default(), &[b"version", b"width", b"height", b"viewBox", b"preserveAspectRatio"])
        } else if k == b"g" || k == b"switch" {
            metadata || common
        } else if k == b"a" {
            metadata || common || span_eq(source, n, b"href")
        } else if k == b"svg" {
            metadata || common || one_of(span_bytes(source, n).unwrap_or_default(),
                &[b"x", b"y", b"width", b"height", b"viewBox", b"preserveAspectRatio"])
        } else { metadata || common || shape || xml_space };
        if !ok { return false; }
    }
    true
}

fn shape_attribute(source: &[u8], name: XmlSpan, kind: XmlSpan) -> bool {
    let (n, k) = (span_bytes(source, name).unwrap_or_default(), span_bytes(source, kind).unwrap_or_default());
    if k == b"rect" { one_of(n, &[b"x", b"y", b"width", b"height", b"rx", b"ry"]) }
    else if k == b"path" { n == b"d" }
    else if k == b"circle" { one_of(n, &[b"cx", b"cy", b"r"]) }
    else if k == b"ellipse" { one_of(n, &[b"cx", b"cy", b"rx", b"ry"]) }
    else if k == b"line" { one_of(n, &[b"x1", b"y1", b"x2", b"y2"]) }
    else if k == b"polygon" || k == b"polyline" { n == b"points" }
    else if k == b"image" { one_of(n, &[b"x", b"y", b"width", b"height", b"href", b"preserveAspectRatio"]) }
    else if k == b"text" || k == b"tspan" { one_of(n, &[b"x", b"y", b"dx", b"dy"]) }
    else { false }
}

fn validate_tokens(source: &[u8], tokens: &[XmlToken]) -> ReferenceResult<()> {
    for token in tokens {
        for span in [token.source, token.name, token.value, token.prefix, token.local_name] {
            if span_bytes(source, span).is_none() {
                return Err(ReferenceDiagnostic::new(ReferenceError::InvalidArgument, span.offset));
            }
        }
    }
    Ok(())
}

fn attributes(tokens: &[XmlToken], element: usize) -> impl Iterator<Item = &XmlToken> {
    let begin = element.saturating_add(1);
    tokens.get(begin..).unwrap_or_default().iter().take_while(|t| t.kind == TokenKind::Attribute)
}

fn attr_value(source: &[u8], tokens: &[XmlToken], element: usize, name: &[u8]) -> Option<XmlSpan> {
    attributes(tokens, element).find(|attr| span_eq(source, attr.local_name, name) && attr.prefix.length == 0)
        .map(|attr| attr.value)
}

fn is_element(kind: TokenKind) -> bool { matches!(kind, TokenKind::StartElement | TokenKind::EmptyElement) }
fn span_bytes(source: &[u8], span: XmlSpan) -> Option<&[u8]> {
    let end = span.offset.checked_add(span.length)?;
    source.get(span.offset..end)
}
fn span_eq(source: &[u8], span: XmlSpan, bytes: &[u8]) -> bool { span_bytes(source, span) == Some(bytes) }
fn one_of(bytes: &[u8], choices: &[&[u8]]) -> bool { choices.contains(&bytes) }
fn matches_any(source: &[u8], span: XmlSpan, choices: &[&[u8]]) -> bool {
    span_bytes(source, span).is_some_and(|bytes| one_of(bytes, choices))
}
fn spans_equal(source: &[u8], left: XmlSpan, right: XmlSpan) -> ReferenceResult<bool> {
    let left = span_bytes(source, left).ok_or_else(|| ReferenceDiagnostic::new(ReferenceError::InvalidArgument, left.offset))?;
    let right = span_bytes(source, right).ok_or_else(|| ReferenceDiagnostic::new(ReferenceError::InvalidArgument, right.offset))?;
    Ok(left == right)
}
fn span_hash(source: &[u8], span: XmlSpan) -> ReferenceResult<u64> {
    Ok(hash_bytes(span_bytes(source, span).ok_or_else(|| ReferenceDiagnostic::new(ReferenceError::InvalidArgument, span.offset))?))
}
fn hash_bytes(bytes: &[u8]) -> u64 {
    bytes.iter().fold(1_469_598_103_934_665_603u64, |hash, byte| {
        (hash ^ u64::from(*byte)).wrapping_mul(1_099_511_628_211)
    })
}
use vexel_svg_reference::{
    attributes_supported, definition_end, use_attributes_supported, xlink_is_bound,
    ReferenceDiagnostic, ReferenceError, ReferenceIndex, MAX_REFERENCE_IDS,
    REFERENCE_SLOT_CAPACITY,
};
use vexel_xml::{tokenize_large, TokenKind, XmlSpan, XmlToken};

fn parsed(source: &[u8]) -> Vec<XmlToken> {
    let (tokens, result) = tokenize_large(source);
    assert_eq!(result.diagnostic.category, vexel_xml::XmlError::None, "{result:?}");
    tokens
}

fn attr<'a>(source: &'a [u8], tokens: &[XmlToken], element: usize, local: &[u8]) -> XmlSpan {
    tokens[element + 1..].iter().take_while(|t| t.kind == TokenKind::Attribute)
        .find(|t| t.local_name.slice(source) == Some(local) && t.prefix.length == 0)
        .expect("expected attribute").value
}

#[test]
fn empty_index_has_no_slot_storage_and_lookup_is_a_miss() {
    let source = b"<svg/>";
    let tokens = parsed(source);
    let mut index = ReferenceIndex::create(source, &tokens).unwrap();
    assert_eq!(index.id_count(), 0);
    assert_eq!(index.storage_bytes(), 0);
    assert_eq!(index.lookup_probes(), 0);
    assert_eq!(index.find(XmlSpan { offset: 0, length: 1 }), None);
    assert_eq!(index.lookup_probes(), 0);
}

#[test]
fn indexed_raw_ids_duplicate_detection_and_probe_accounting_match_contract() {
    let source = b"<svg><g id='a&amp;b'/><rect id='a&#38;b'/></svg>";
    let tokens = parsed(source);
    let raw = attr(source, &tokens, 1, b"id");
    let other = attr(source, &tokens, 3, b"id");
    let mut index = ReferenceIndex::create(source, &tokens).unwrap();
    assert_eq!(index.id_count(), 2);
    assert_eq!(index.storage_bytes(), REFERENCE_SLOT_CAPACITY * core::mem::size_of::<u32>());
    assert_eq!(index.find(raw), Some(1));
    assert_eq!(index.find(other), Some(3));
    let before_miss = index.lookup_probes();
    assert_eq!(index.find(XmlSpan { offset: 0, length: 4 }), None);
    assert!(index.lookup_probes() > before_miss);
    assert_eq!(index.find(XmlSpan { offset: usize::MAX, length: 1 }), None);
    assert_eq!(index.find(XmlSpan { offset: raw.offset, length: 0 }), None);

    assert_ne!(raw.slice(source), other.slice(source));
}

#[test]
fn empty_and_duplicate_ids_fail_without_publishing_a_partial_index() {
    for (source, expected, offset) in [
        (&b"<svg><g id=''/></svg>"[..], ReferenceError::Unsupported, 12usize),
        (&b"<svg><g id='x'/><g id='x'/></svg>"[..], ReferenceError::Unsupported, 23usize),
    ] {
        let tokens = parsed(source);
        let result = ReferenceIndex::create(source, &tokens);
        let error = result.unwrap_err();
        assert_eq!(error.category, expected);
        assert_eq!(error.offset, offset);
    }
}

#[test]
fn exact_hash_collisions_probe_until_the_raw_key_matches() {
    let mut by_bucket = std::collections::BTreeMap::<usize, Vec<String>>::new();
    let mut collision = None;
    for n in 0..100_000usize {
        let id = format!("key{n}");
        let bucket = id.bytes().fold(1_469_598_103_934_665_603u64, |hash, byte| {
            (hash ^ u64::from(byte)).wrapping_mul(1_099_511_628_211)
        }) as usize & (REFERENCE_SLOT_CAPACITY - 1);
        let ids = by_bucket.entry(bucket).or_default();
        ids.push(id);
        if ids.len() == 3 { collision = Some(ids.clone()); break; }
    }
    let ids = collision.expect("pigeonhole search finds a bucket with three keys");
    let mut source = String::from("<svg>");
    for id in &ids { source.push_str(&format!("<g id='{id}'/>")); }
    source.push_str("</svg>");
    let tokens = parsed(source.as_bytes());
    let spans: Vec<_> = [1usize, 3, 5].iter().map(|&element| attr(source.as_bytes(), &tokens, element, b"id")).collect();
    let mut index = ReferenceIndex::create(source.as_bytes(), &tokens).unwrap();
    for (expected, span) in [1usize, 3, 5].into_iter().zip(spans) {
        assert_eq!(index.find(span), Some(expected));
    }
    assert!(index.lookup_probes() >= 6);
}

#[test]
fn id_cap_accepts_exactly_the_limit_and_rejects_the_next_identifier() {
    let mut source = String::from("<svg>");
    for n in 0..MAX_REFERENCE_IDS { source.push_str(&format!("<g id='i{n}'/>")); }
    source.push_str("</svg>");
    let tokens = parsed(source.as_bytes());
    let index = ReferenceIndex::create(source.as_bytes(), &tokens).unwrap();
    assert_eq!(index.id_count(), MAX_REFERENCE_IDS);
    assert_eq!(index.storage_bytes(), REFERENCE_SLOT_CAPACITY * size_of::<u32>());

    source.insert_str(source.len() - b"</svg>".len(), "<g id='overflow'/>");
    let tokens = parsed(source.as_bytes());
    let error = ReferenceIndex::create(source.as_bytes(), &tokens).unwrap_err();
    assert_eq!(error.category, ReferenceError::Limit);
    assert!(error.offset < source.len());
}

#[test]
fn malformed_token_spans_are_rejected_before_index_creation_or_helpers_read_them() {
    let source = b"<svg><g id='x'/></svg>";
    let mut tokens = parsed(source);
    let attr_index = tokens.iter().position(|token| token.kind == TokenKind::Attribute).unwrap();
    tokens[attr_index].value = XmlSpan { offset: usize::MAX, length: 1 };
    assert_eq!(ReferenceIndex::create(source, &tokens).unwrap_err(), ReferenceDiagnostic {
        category: ReferenceError::InvalidArgument, offset: usize::MAX,
    });
    assert_eq!(definition_end(source, &tokens, 0), None);
    assert!(!xlink_is_bound(source, &tokens));
    assert!(!use_attributes_supported(source, &tokens, 1));
}

#[test]
fn definition_end_matches_supported_containers_and_depth() {
    let source = b"<svg><defs><g><defs/><symbol><path/></symbol></g></defs><marker/><a/></svg>";
    let tokens = parsed(source);
    let outer = tokens.iter().position(|t| t.kind == TokenKind::StartElement && t.local_name.slice(source) == Some(b"defs")).unwrap();
    let close = tokens.iter().position(|t| t.kind == TokenKind::EndElement && t.local_name.slice(source) == Some(b"defs")).unwrap();
    assert_eq!(definition_end(source, &tokens, outer), Some(close));
    let empty = tokens.iter().position(|t| t.kind == TokenKind::EmptyElement && t.local_name.slice(source) == Some(b"marker")).unwrap();
    assert_eq!(definition_end(source, &tokens, empty), Some(empty));
    let ordinary = tokens.iter().position(|t| t.kind == TokenKind::EmptyElement && t.local_name.slice(source) == Some(b"a")).unwrap();
    assert_eq!(definition_end(source, &tokens, ordinary), None);
}

#[test]
fn attribute_allowlists_preserve_root_shape_namespace_and_foreign_rules() {
    let source = b"<svg xmlns:xlink='http://www.w3.org/1999/xlink' width='8' foreign:label='kept'><rect x='1' width='2' foreign:label='kept'/><path x='1'/></svg>";
    let tokens = parsed(source);
    let root = tokens.iter().position(|t| t.kind == TokenKind::StartElement).unwrap();
    let rect = tokens.iter().position(|t| t.kind == TokenKind::EmptyElement && t.local_name.slice(source) == Some(b"rect")).unwrap();
    let path = tokens.iter().position(|t| t.kind == TokenKind::EmptyElement && t.local_name.slice(source) == Some(b"path")).unwrap();
    let rect_kind = tokens[rect].local_name;
    let path_kind = tokens[path].local_name;
    assert!(attributes_supported(source, &tokens, root, true, tokens[root].local_name));
    assert!(attributes_supported(source, &tokens, rect, false, rect_kind));
    assert!(!attributes_supported(source, &tokens, path, false, path_kind));

    let bad = b"<svg><rect svg:width='2'/></svg>";
    let bad_tokens = parsed(bad);
    let rect = bad_tokens.iter().position(|t| t.kind == TokenKind::EmptyElement).unwrap();
    assert!(!attributes_supported(bad, &bad_tokens, rect, false, bad_tokens[rect].local_name));
}

#[test]
fn every_legacy_common_and_use_attribute_name_remains_supported() {
    let common = [
        "fill", "fill-rule", "transform", "clip-path", "filter", "mask",
        "mix-blend-mode", "isolation", "vector-effect", "shape-rendering",
        "paint-order", "marker", "marker-start", "marker-mid", "marker-end",
        "mask-type", "color-interpolation-filters", "systemLanguage",
        "requiredFeatures", "requiredExtensions", "fill-opacity", "stroke-opacity",
        "opacity", "visibility", "display", "color", "stroke", "stroke-width",
        "stroke-linecap", "stroke-linejoin", "stroke-miterlimit", "stroke-dasharray",
        "stroke-dashoffset", "font-family", "font-size", "font-weight", "font-style",
        "text-anchor", "letter-spacing", "word-spacing",
    ];
    let root_only = ["xmlns", "version", "width", "height", "viewBox", "preserveAspectRatio"];
    let use_allowed = [
        "href", "id", "class", "style", "x", "y", "width", "height",
        "preserveAspectRatio", "fill", "fill-rule", "fill-opacity", "stroke-opacity",
        "opacity", "visibility", "display", "color", "transform", "clip-path",
        "filter", "mask", "mix-blend-mode", "isolation", "vector-effect",
        "shape-rendering", "paint-order", "marker", "marker-start", "marker-mid",
        "marker-end", "mask-type", "color-interpolation-filters", "stroke",
        "stroke-width", "stroke-linecap", "stroke-linejoin", "stroke-miterlimit",
        "stroke-dasharray", "stroke-dashoffset", "font-family", "font-size",
        "font-weight", "font-style", "text-anchor", "letter-spacing", "word-spacing",
    ];
    for name in common {
        let source = format!("<svg {name}='v'/>");
        let tokens = parsed(source.as_bytes());
        let root = tokens.iter().position(|t| t.kind == TokenKind::EmptyElement).unwrap();
        assert!(attributes_supported(source.as_bytes(), &tokens, root, true, tokens[root].local_name), "root {name}");
    }
    for name in root_only {
        let source = format!("<svg {name}='v'/>");
        let tokens = parsed(source.as_bytes());
        let root = tokens.iter().position(|t| t.kind == TokenKind::EmptyElement).unwrap();
        assert!(attributes_supported(source.as_bytes(), &tokens, root, true, tokens[root].local_name), "root {name}");
    }
    for name in use_allowed {
        let source = format!("<svg><use {name}='v'/></svg>");
        let tokens = parsed(source.as_bytes());
        let use_index = tokens.iter().position(|t| t.kind == TokenKind::EmptyElement).unwrap();
        assert!(use_attributes_supported(source.as_bytes(), &tokens, use_index), "use {name}");
    }
    for name in ["id", "class", "style"] {
        let source = format!("<svg {name}='v'><use {name}='v'/></svg>");
        let tokens = parsed(source.as_bytes());
        let root = tokens.iter().position(|t| t.kind == TokenKind::StartElement).unwrap();
        let use_index = tokens.iter().position(|t| t.kind == TokenKind::EmptyElement).unwrap();
        assert!(attributes_supported(source.as_bytes(), &tokens, root, true, tokens[root].local_name));
        assert!(use_attributes_supported(source.as_bytes(), &tokens, use_index));
    }
}

#[test]
fn xlink_binding_uses_root_namespace_and_use_allowlist_is_complete() {
    let good = b"<svg xmlns:xlink='http://www.w3.org/1999/xlink'><use xlink:href='#x' transform='translate(1 2)'/></svg>";
    let tokens = parsed(good);
    let use_index = tokens.iter().position(|t| t.kind == TokenKind::EmptyElement).unwrap();
    assert!(xlink_is_bound(good, &tokens));
    assert!(use_attributes_supported(good, &tokens, use_index));

    let wrong_uri = b"<svg xmlns:xlink='urn:wrong'><use xlink:href='#x'/></svg>";
    let wrong_tokens = parsed(wrong_uri);
    let use_index = wrong_tokens.iter().position(|t| t.kind == TokenKind::EmptyElement).unwrap();
    assert!(!xlink_is_bound(wrong_uri, &wrong_tokens));
    assert!(!use_attributes_supported(wrong_uri, &wrong_tokens, use_index));

    let nested_binding = b"<svg><g xmlns:xlink='http://www.w3.org/1999/xlink'><use xlink:href='#x'/></g></svg>";
    let nested_tokens = parsed(nested_binding);
    let nested_use = nested_tokens.iter().position(|t| t.kind == TokenKind::EmptyElement).unwrap();
    assert!(!xlink_is_bound(nested_binding, &nested_tokens));
    assert!(!use_attributes_supported(nested_binding, &nested_tokens, nested_use));

    let bad_attr = b"<svg><use href='#x' onload='bad'/></svg>";
    let bad_tokens = parsed(bad_attr);
    let use_index = bad_tokens.iter().position(|t| t.kind == TokenKind::EmptyElement).unwrap();
    assert!(!use_attributes_supported(bad_attr, &bad_tokens, use_index));
}

